--  v_cargo:=coalesce(v_save->'cargo','{}'::jsonb);
--  IF jsonb_typeof(v_cargo)<>'object' THEN RAISE EXCEPTION 'ORE_GRANT_CARGO_INVALID'; END IF;
--  v_prev:=coalesce((v_cargo->>p_resource)::bigint,0);
