--  v_volley:=ceil(v_hp/greatest(1,v_damage * v_accuracy * (1 + least(0.3,greatest(0,coalesce((p_combat->>'shield_pressure')::numeric,0))) * coalesce((f.snapshot#>>'{npc,shield}')::numeric,0)/v_hp)))::integer;
