-- -- V48 • Acesso ao Autopilot exclusivo por autorização do servidor.
-- -- Não libera pagamentos, Premium, passe nem compra na loja.
-- -- Seguro para executar novamente: não habilita nenhum jogador automaticamente.
-- BEGIN;
